using System;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 Dictionary<string,List<BackupDemand>> SourcesByItem(List<BackupDemand> demands,out List<BackupDemand> unmapped){var result=new Dictionary<string,List<BackupDemand>>();unmapped=new List<BackupDemand>();var targets=backupBill.Select(b=>b.Target).ToList();foreach(var d in demands){string slot;BackupTarget target;if(backupBillRoutes.TryGetValue(d.Key,out slot))target=targets.FirstOrDefault(t=>t.SlotId==slot);else target=BackupMapping.Suggest(d,targets);if(target==null){if(d.Quantity>1e-10||d.ManualOverride)unmapped.Add(d);continue;}List<BackupDemand> rows;if(!result.TryGetValue(target.SlotId,out rows)){rows=new List<BackupDemand>();result[target.SlotId]=rows;}rows.Add(d);}return result;}
 void AddUnmappedBoqRows(IEnumerable<BackupDemand> items){var rows=items.Where(q=>!q.ManualOverride).ToList();if(rows.Count==0)return;int section=boqGrid.Rows.Add("","COMPUTED QUANTITIES — SELECT BACKUP PAY ITEM ONCE","","");boqGrid.Rows[section].ReadOnly=true;boqGrid.Rows[section].DefaultCellStyle.BackColor=Color.FromArgb(225,233,240);foreach(var q in rows){int n=boqGrid.Rows.Add("",q.Description,q.Quantity.ToString("0.########",CultureInfo.InvariantCulture),q.Unit);boqGrid.Rows[n].ReadOnly=true;boqGrid.Rows[n].Cells[1].ToolTipText="Computed quantity is retained in Tool Kit. Use Map BACKUP items for an ambiguous/new specification; the app does not guess among duplicate pay items.";foreach(var source in q.Sources){int detail=boqGrid.Rows.Add("","    "+source.Description,source.Quantity.ToString("0.########",CultureInfo.InvariantCulture),source.Unit);boqGrid.Rows[detail].ReadOnly=true;boqGrid.Rows[detail].DefaultCellStyle.ForeColor=PowTheme.Muted;}}}
 void UpdateBackupBillDashboard(){var selected=boqGrid.CurrentRow==null?null:boqGrid.CurrentRow.Tag as BackupBillItem;string selectedId=selected==null?null:selected.Slot;int scroll=boqGrid.FirstDisplayedScrollingRowIndex;paintingBackupBill=true;boqGrid.SuspendLayout();try{boqGrid.Rows.Clear();var demands=BackupQuantities(false).Where(d=>d.Quantity>1e-10||d.ManualOverride||d.Sources.Any(s=>s.Quantity>1e-10)||backupBillRoutes.ContainsKey(d.Key)).ToList();List<BackupDemand> unmapped;var grouped=SourcesByItem(demands,out unmapped);foreach(var item in backupBill){List<BackupDemand> sources;if(!grouped.TryGetValue(item.Slot,out sources))sources=new List<BackupDemand>();var matching=sources.Where(d=>BackupMapping.Unit(d.Unit)==BackupMapping.Unit(item.Unit)).ToList();bool computed=matching.Count>0&&BackupMapping.Unit(item.Unit)!="ls";double? quantity=item.ManualQuantity??(computed||matching.Any(d=>d.ManualPriority>=1)?(double?)BackupMapping.FinalQuantity(matching,item.Unit):item.WorkbookQuantity);int index=boqGrid.Rows.Add(item.Code,item.Description,quantity.HasValue?quantity.Value.ToString("0.########",CultureInfo.InvariantCulture):"",item.Unit);var row=boqGrid.Rows[index];row.Tag=item;foreach(DataGridViewCell cell in row.Cells)cell.ReadOnly=true;row.Cells[2].ReadOnly=computed&&!item.ManualQuantity.HasValue;row.Cells[2].Style.BackColor=row.Cells[2].ReadOnly?Color.FromArgb(229,242,242):Color.FromArgb(255,249,222);row.Cells[2].ToolTipText=computed?"Computed from Tool Kit measurements.":"Enter manual quantity here; 1 LS is never inferred. Zero clears quantity; blank removes the override.";foreach(var d in sources)foreach(var source in d.Sources){int detail=boqGrid.Rows.Add("","    "+source.Description,source.Quantity.ToString("0.########",CultureInfo.InvariantCulture),source.Unit);boqGrid.Rows[detail].ReadOnly=true;boqGrid.Rows[detail].DefaultCellStyle.ForeColor=PowTheme.Muted;}}
 AddUnmappedBoqRows(unmapped);AddLegacyBoqRows();var issues=WorksValidationIssues();boqStatus.ForeColor=issues.Count>0?Color.Firebrick:PowTheme.Teal;boqStatus.Text=backupBill.Count+" BACKUP pay items | computed quantities update here immediately"+(unmapped.Count>0?" | "+unmapped.Count+" source(s) need one-time mapping":"")+(issues.Count>0?" | Resolve input issues before exporting":"");}finally{boqGrid.ResumeLayout();paintingBackupBill=false;if(selectedId!=null){var row=boqGrid.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>r.Tag is BackupBillItem&&((BackupBillItem)r.Tag).Slot==selectedId);if(row!=null)boqGrid.CurrentCell=row.Cells[2];}if(boqGrid.IsHandleCreated&&scroll>=0&&scroll<boqGrid.Rows.Count)boqGrid.FirstDisplayedScrollingRowIndex=scroll;}}
 void AddLegacyBoqRows(){if(plumbingLs==null)return;foreach(DataGridViewRow item in plumbingLs.Rows){if(item.IsNewRow||Cell(item,6)!=""||Cell(item,2)=="")continue;int n=boqGrid.Rows.Add("",Cell(item,2),Cell(item,3),Cell(item,5));var row=boqGrid.Rows[n];row.Tag=item;foreach(DataGridViewCell cell in row.Cells)cell.ReadOnly=true;row.Cells[2].ReadOnly=false;row.Cells[2].Style.BackColor=Color.FromArgb(255,249,222);}}
}
}
